questionvariables.text:
/* Reverse engineer to ensure clean integer answers within the [-6, 6] graph bounds */
bound : rand_with_step(-4, 4, 1);

b : rand_with_step(2, 5, 1); 
a : rand_with_step(2, 10, 1);

/* We want the equation to be a - b*x <= c.
   Since the answer is x >= bound, multiplying by -b flips it: -b*x <= -b*bound
   Adding 'a': a - b*x <= a - b*bound. 
   Therefore, c = a - b*bound. */
c : a - b * bound;

/* Teacher's exact answers */
ta1 : x >= bound;
ta2 : [bound, 0]; /* The coordinate of the dragged point on the x-axis */

/* Mistake Catchers for Algebra */
wrong_sign : x <= bound;
wrong_c : c + a;
wrong_bound : wrong_c / (-b);
wrong_op : x >= wrong_bound;
